import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.BjkiRu3Q.js";const h=JSON.parse('{"title":"Γλωσσάρι όρων","description":"","frontmatter":{},"headers":[],"relativePath":"el/help/glossary.md","filePath":"el/help/glossary.md"}'),o={name:"el/help/glossary.md"};function l(s,t,n,i,c,p){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="γλωσσαρι-ορων" tabindex="-1">Γλωσσάρι όρων <a class="header-anchor" href="#γλωσσαρι-ορων" aria-label="Permalink to &quot;Γλωσσάρι όρων&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Αναφορά v0.7.26, όχι έλεγχος ζωντανής εγκατάστασης ή έγκριση εμπορικής λειτουργίας. Ελέγξτε έκδοση, δικαιώματα, ρυθμίσεις και αποδοχή.</p></div><p>Οι όροι εξηγούν τη σημασία τους στην επιχειρησιακή τεκμηρίωση, όχι νομικούς ή λογιστικούς ορισμούς.</p><table tabindex="0"><thead><tr><th>Όρος</th><th>Σημασία</th></tr></thead><tbody><tr><td>Εταιρικός χώρος (tenant)</td><td>Το όριο δεδομένων και εξουσιοδότησης ανά εταιρεία.</td></tr><tr><td>Αγορά / περιοχή λειτουργίας</td><td>Ρυθμισμένη περιοχή εξυπηρέτησης με επιχειρησιακές ρυθμίσεις.</td></tr><tr><td>Κατάλογος τοποθεσιών</td><td>Εγκεκριμένα σημεία αναφοράς παραλαβής και αποβίβασης.</td></tr><tr><td>Κανάλι κρατήσεων</td><td>Ρυθμισμένη προέλευση κρατήσεων· ενεργή ένδειξη δεν εγκρίνει δημόσια λήψη.</td></tr><tr><td>Κράτηση</td><td>Αποθηκευμένο αίτημα και κύκλος ζωής υπηρεσίας, όχι απαραίτητα εξοφλημένο ή ανατεθειμένο.</td></tr><tr><td>Προσφορά</td><td>Πρόταση τιμής υπό κανόνες και έλεγχο.</td></tr><tr><td>Επαληθευμένος ναύλος</td><td>Τιμή επαληθευμένη από κανόνες backend· έλλειψη επαλήθευσης απαιτεί έλεγχο.</td></tr><tr><td>Χειροκίνητη προσφορά</td><td>Τιμή ελεγμένη από χειριστή όταν δεν υπάρχει αυτόματος έγκυρος ναύλος.</td></tr><tr><td>Σκέλος διαδρομής</td><td>Ανεξάρτητο τμήμα μετάβασης ή επιστροφής.</td></tr><tr><td>Ανάθεση (dispatch)</td><td>Εξουσιοδοτημένη διάθεση πόρων σε κράτηση ή σκέλος.</td></tr><tr><td>Χρονικό περιθώριο ανάθεσης</td><td>Ρυθμισμένο περιθώριο προγραμματισμού· όχι εγγύηση διαθεσιμότητας.</td></tr><tr><td>Κατηγορία οχήματος</td><td>Κατηγορία υπηρεσίας και αναφορά χωρητικότητας/τιμής, διαφορετική από φυσικό όχημα.</td></tr><tr><td>Κατάλογος οδηγών</td><td>Επιχειρησιακές εγγραφές οδηγών, χωριστές από λογαριασμούς σύνδεσης.</td></tr><tr><td>Εταιρική συμμετοχή / RBAC</td><td>Συμμετοχή και έλεγχος πρόσβασης βάσει ρόλου που ορίζουν επιτρεπόμενες ενέργειες.</td></tr><tr><td>Άδεια κοινοποίησης GPS</td><td>Χρονικά περιορισμένη εξουσιοδότηση ρητής κοινοποίησης θέσης οδηγού.</td></tr><tr><td>Γεωγραφικό όριο (geofence)</td><td>Γεωγραφικό όριο αξιολόγησης θέσης σε σχέση με ρυθμισμένη περιοχή.</td></tr><tr><td>ETA</td><td>Εκτιμώμενος χρόνος άφιξης, όχι επιβεβαιωμένη άφιξη.</td></tr><tr><td>Παρατήρηση άφιξης</td><td>Χρονοσημασμένο τεκμήριο κατάστασης άφιξης.</td></tr><tr><td>Ειδοποίηση ανάθεσης</td><td>Πρόταση που απαιτεί έλεγχο πριν από επιχειρησιακή αλλαγή.</td></tr><tr><td>CRM</td><td>Εγγραφές σχέσεων πελατών και σύνδεση επαναλαμβανόμενων πελατών.</td></tr><tr><td>Συνεργάτης (affiliate)</td><td>Εμπορικός συνεργάτης με συμφωνημένη παραπομπή ή προμήθεια.</td></tr><tr><td>Υπεργολάβος</td><td>Εξωτερικός προμηθευτής μεταφοράς που αναλαμβάνει υπηρεσία ή σκέλος.</td></tr><tr><td>Υποχρέωση προμηθευτή</td><td>Καταγεγραμμένο εκκρεμές ποσό προς προμηθευτή, υπό συμφωνία.</td></tr><tr><td>Έγκριση πληρωμής</td><td>Έγκριση ή δέσμευση ποσού από πάροχο· όχι απαραίτητα είσπραξη ή διακανονισμός.</td></tr><tr><td>Είσπραξη μετρητών</td><td>Καταγραφή μετρητών που πραγματικά παραλήφθηκαν από επιβάτη.</td></tr><tr><td>Παράδοση μετρητών</td><td>Χωριστή επιβεβαίωση φυσικής μεταβίβασης φύλαξης στο γραφείο.</td></tr><tr><td>Συμφωνία συναλλαγών</td><td>Αντιστοίχιση καταγεγραμμένων συναλλαγών με επαληθευμένα τεκμήρια.</td></tr><tr><td>PSP</td><td>Πάροχος υπηρεσιών πληρωμών· ετοιμότητα διασύνδεσης δεν σημαίνει ενεργοποίηση.</td></tr><tr><td>Webhook</td><td>Callback παρόχου σε endpoint εφαρμογής· απαιτεί έλεγχο γνησιότητας και διπλών συμβάντων.</td></tr><tr><td>Ιδιοδυναμία (idempotency)</td><td>Προστασία από ανεπιθύμητα διπλά αποτελέσματα σε επανάληψη αιτήματος.</td></tr><tr><td>Ουρά αποστολής (outbox)</td><td>Μόνιμη ουρά εργασιών ειδοποιήσεων και κατάστασης επεξεργασίας.</td></tr><tr><td>Εξαίρεση (opt-out)</td><td>Καταγεγραμμένος περιορισμός αποστολής σε παραλήπτη ή κανάλι.</td></tr><tr><td>Ανάληψη από χειριστή</td><td>Κλιμάκωση συνομιλίας σε εξουσιοδοτημένο άνθρωπο.</td></tr><tr><td>Sandbox</td><td>Ελεγχόμενη δοκιμαστική λειτουργία ή περιβάλλον, όχι απόδειξη ζωντανής υπηρεσίας.</td></tr><tr><td>Ασφαλής αποκλεισμός (fail-closed)</td><td>Η ενέργεια παραμένει αποκλεισμένη όταν λείπει απαιτούμενη έγκριση ή ετοιμότητα.</td></tr><tr><td>Migration</td><td>Έκδοση αλλαγής σχήματος ή δεδομένων που απαιτεί έλεγχο ανά έκδοση.</td></tr><tr><td>Αποδοχή έκδοσης</td><td>Καταγεγραμμένο τεκμήριο ότι έκδοση και ροή πληρούν συμφωνημένους ελέγχους.</td></tr><tr><td>RPO / RTO</td><td>Συμφωνημένοι στόχοι σημείου και χρόνου ανάκτησης, που πρέπει να δοκιμάζονται.</td></tr></tbody></table>',4)])])}const b=d(o,[["render",l]]);export{h as __pageData,b as default};
